    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def is_perfect_cube(n):
    if n < 0:
        return None
    if n == 0:
        return 0
    # Use floating point cube root and check nearby integers for robustness
    # Rounding to the nearest integer should give the root if it's an integer
    k_float = n**(1/3)
    k_candidate = round(k_float)

    # Check k_candidate and its neighbors due to float precision issues
    for k in range(max(1, k_candidate - 1), k_candidate + 2):
        if k**3 == n:
            return k
    return None

def find_candidates(limit):
